%[text] # BEV Controller - Simulation Case
model_name = "HarnessModel_BEVController";
load_system(model_name) 

BEVController_Basic_params

loadLUTData_BEVController_Random

sim_in = Simulink.SimulationInput(model_name);

sim_in = setBlockParameter(sim_in, model_name + "/BEV Speed Tracking Controller", ...
  ReferencedSubsystem = "BEVController_Basic_refsub");

sim_in = setModelParameter(sim_in, StopTime = "2000");

applyToModel(sim_in)
sim_out = sim(sim_in);
%%
result = extractTimetable(sim_out.logsout);
var_names = string(result.Properties.VariableNames)';
var_units = string(result.Properties.VariableUnits)';
%[text] 
target_signal = "Vehicle speed input kph";
fig = figure; %[output:887dd335]
fig.Position(3:4) = [700 300];  % width height %[output:887dd335]
plot(result, "Time", target_signal, LineWidth=2) %[output:887dd335]
hold on;  grid on;  axis padded %[output:887dd335]
title(target_signal) %[output:887dd335]
ylabel(var_units( var_names==target_signal )) %[output:887dd335]
target_signal = "Motor torque command";
fig = figure; %[output:9c186f67]
fig.Position(3:4) = [700 300];  % width height %[output:9c186f67]
plot(result, "Time", target_signal, LineWidth=2) %[output:9c186f67]
hold on;  grid on;  axis padded %[output:9c186f67]
title(target_signal) %[output:9c186f67]
ylabel(var_units( var_names==target_signal )) %[output:9c186f67]
